/* STEFY DALSZÖVEGEK · local-first application */
const DB_NAME='stefy-songbook', DB_VERSION=1, STORE='library';
const DEFAULT={songs:[],tags:['Mulatós','Lakodalmas','Lassú','Romantikus','Csárdás'],gigs:[],recent:[],sort:'title',settings:{theme:'night',font:23,line:1.65,wake:true,orientation:'auto',brightness:0,overlay:.83,background:''}};
let state={...DEFAULT},db=null,page='home',query='',activeTag='',editorId=null,currentSongId=null,readerContext=null,returnPage='home',activeGigId=null,modal=null,toastTimer=null,importPayload=null,dragId=null;
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function uid(){return crypto?.randomUUID?.()||`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`}
function localDate(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function idbOpen(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>req.result.createObjectStore(STORE);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function loadState(){try{db=await idbOpen();const v=await new Promise((resolve,reject)=>{const r=db.transaction(STORE).objectStore(STORE).get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(v)state={...DEFAULT,...v,settings:{...DEFAULT.settings,...v.settings}}}catch(e){try{state={...DEFAULT,...JSON.parse(localStorage.getItem('stefy-songbook')||'{}')}}catch{state={...DEFAULT}}}}
async function persist(){try{if(!db)db=await idbOpen();await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(state,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch{try{localStorage.setItem('stefy-songbook',JSON.stringify(state));notify('Helyi mentés frissítve.')}catch{notify('A mentés nem sikerült. Ellenőrizd a készülék tárhelyét.')}}}
const songById=id=>state.songs.find(s=>s.id===id), gigById=id=>state.gigs.find(g=>g.id===id), dateLabel=d=>{if(!d)return 'Dátum nélkül';const x=new Date(d+'T12:00:00');return isNaN(x)?d:new Intl.DateTimeFormat('hu-HU',{year:'numeric',month:'long',day:'numeric'}).format(x)}, shortDate=d=>{if(!d)return '♫';const x=new Date(d+'T12:00:00');return isNaN(x)?'♫':`${String(x.getMonth()+1).padStart(2,'0')}.${String(x.getDate()).padStart(2,'0')}`};
function notify(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function setPage(p){page=p;activeTag='';query='';render();window.scrollTo(0,0)}
function filteredSongs(list=state.songs,q=query){const n=q.trim().toLocaleLowerCase('hu');let a=list.filter(s=>!n||[s.title,s.artist,s.lyrics,...(s.tags||[])].join(' ').toLocaleLowerCase('hu').includes(n));switch(state.sort){case'recent':a.sort((x,y)=>(y.lastOpened||'').localeCompare(x.lastOpened||''));break;case'favorite':a.sort((x,y)=>Number(y.favorite)-Number(x.favorite)||x.title.localeCompare(y.title,'hu'));break;case'newest':a.sort((x,y)=>(y.createdAt||'').localeCompare(x.createdAt||''));break;default:a.sort((x,y)=>x.title.localeCompare(y.title,'hu'))}return a}
function songRows(songs,{number=false,remove=false}={}){if(!songs.length)return `<div class="empty"><div class="empty-icon">♫</div><h3>Még nincs itt dal</h3><p>Adj hozzá egy dalt, vagy próbálj más keresőkifejezést.</p><button class="btn primary" data-action="new-song">＋ Új dal</button></div>`;return `<div class="song-list">${songs.map((s,i)=>`<div class="song-row" data-action="open-song" data-id="${esc(s.id)}" role="button" tabindex="0">${number?`<span class="row-number">${i+1}.</span>`:''}<span class="song-title">${esc(s.title)}${s.artist?`<span class="song-artist">${esc(s.artist)}</span>`:''}</span>${s.favorite?'<span class="row-star">★</span>':''}${remove?`<button class="row-more" data-action="remove-gig-song" data-id="${esc(s.id)}" aria-label="Eltávolítás">×</button>`:''}</div>`).join('')}</div>`}
function pageHeader(kicker,title,subtitle,button=''){return `<div class="eyebrow">${kicker}</div><div class="section-head" style="margin:10px 0 4px"><h1 style="margin:0">${title}</h1>${button}</div>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}`}
function homeView(){const recent=state.recent.map(id=>songById(id)).filter(Boolean).slice(0,5);return `<section class="hero"><div class="hero-copy"><div class="eyebrow">SAJÁT ZENÉSZ-KÖNYVED</div><h1>A dalaid.<br><span class="gold-text">Mindig kéznél.</span></h1><p class="subtitle">Gyorsan megtalálod, tisztán olvasod — akár a színpadon, akár internet nélkül.</p></div><button class="btn primary large" data-action="new-song">＋ Új dal felvétele</button></section><label class="searchbox"><span>⌕</span><input id="homeSearch" placeholder="Dal keresése..." autocomplete="off"><span style="font-size:11px;color:#70798a">↵</span></label><div class="search-hint">Keresés címben, előadóban, címkékben és a dalszövegben</div><div class="quick-grid"><button class="quick-card" data-action="page" data-page="favorites"><span class="qicon">★</span><strong>Kedvencek</strong><small>${state.songs.filter(s=>s.favorite).length} dal</small></button><button class="quick-card" data-action="page" data-page="recent"><span class="qicon">◷</span><strong>Legutóbbi dalok</strong><small>Utoljára megnyitottak</small></button><button class="quick-card" data-action="page" data-page="gigs"><span class="qicon">♫</span><strong>Fellépés mód</strong><small>${state.gigs.length} lista</small></button><button class="quick-card" data-action="page" data-page="tags"><span class="qicon">▦</span><strong>Kategóriák</strong><small>${state.tags.length} címke</small></button><button class="quick-card" data-action="new-song"><span class="qicon">＋</span><strong>Új dal</strong><small>Felvétel pár lépésben</small></button></div><div class="section-head"><h3>Legutóbbi dalok</h3><button class="btn ghost" data-action="page" data-page="recent">Összes megtekintése →</button></div>${recent.length?songRows(recent):`<div class="empty"><div class="empty-icon">♫</div><h3>Kezdjük az első dallal</h3><p>A dalaid ezen a készüléken maradnak, és internet nélkül is elérhetők.</p><button class="btn primary" data-action="new-song">＋ Új dal</button></div>`}`}
function songsView(){let arr=filteredSongs();if(activeTag)arr=arr.filter(s=>(s.tags||[]).includes(activeTag));return `${pageHeader(activeTag?'CÍMKE': 'ZENÉSZ-KÖNYV',activeTag?esc(activeTag):'Dalok',`${arr.length} dal · a listában csak a címek jelennek meg`)}<div class="toolbar"><label class="searchbox"><span>⌕</span><input id="songSearch" value="${esc(query)}" placeholder="Keresés a teljes dalszövegben…"></label><select class="select" id="sortSelect" aria-label="Rendezés"><option value="title" ${state.sort==='title'?'selected':''}>🔤 Cím szerint</option><option value="recent" ${state.sort==='recent'?'selected':''}>◷ Legutóbb használt</option><option value="favorite" ${state.sort==='favorite'?'selected':''}>★ Kedvencek elöl</option><option value="newest" ${state.sort==='newest'?'selected':''}>＋ Legújabban hozzáadott</option></select><button class="btn primary" data-action="new-song">＋ Új dal</button></div>${state.tags.length?`<div class="tag-line" style="margin:-4px 0 16px"><button class="tag-option ${!activeTag?'selected':''}" data-action="tag-filter" data-tag="">Mindegyik</button>${state.tags.map(t=>`<button class="tag-option ${activeTag===t?'selected':''}" data-action="tag-filter" data-tag="${esc(t)}">${esc(t)}</button>`).join('')}</div>`:''}${songRows(arr)}`}
function favoritesView(){const a=filteredSongs(state.songs.filter(s=>s.favorite));return `${pageHeader('SAJÁT VÁLOGATÁS','Kedvencek',`${a.length} kedvenc dal`)}${songRows(a)}`}
function recentView(){const a=state.recent.map(id=>songById(id)).filter(Boolean);return `${pageHeader('GYORS ELÉRÉS','Legutóbbi dalok','Az utolsó 20 megnyitott dalad, automatikusan frissülve.')}${songRows(a,{number:true})}`}
function songEditor(){const song=editorId?songById(editorId):null,sel=new Set(song?.tags||[]);return `<div style="max-width:780px">${pageHeader(song?'DALSZÖVEG-KÖNYV':'ÚJ DAL',song?'Dal szerkesztése':'Új dal','A változtatásokat csak ezen a készüléken mentjük.')}<form id="songForm" class="panel form-grid" style="margin-top:21px"><div class="two-col"><div class="field"><label for="title">Cím *</label><input id="title" name="title" required maxlength="180" value="${esc(song?.title||'')}" placeholder="A dal címe"></div><div class="field"><label for="artist">Előadó <span class="small-muted">(nem kötelező)</span></label><input id="artist" name="artist" maxlength="120" value="${esc(song?.artist||'')}" placeholder="Előadó neve"></div></div><div class="field"><label for="lyrics">Dalszöveg *</label><textarea id="lyrics" name="lyrics" required placeholder="Írd vagy másold ide a teljes dalszöveget…">${esc(song?.lyrics||'')}</textarea><span class="help">Új bekezdéshez hagyj üres sort.</span></div><div class="field"><label>Címkék</label><div class="tag-picker">${state.tags.map(t=>`<button type="button" class="tag-option ${sel.has(t)?'selected':''}" data-action="toggle-edit-tag" data-tag="${esc(t)}">${esc(t)}</button>`).join('')||'<span class="small-muted">Még nincs címke. A címkéket a Kategóriák oldalon hozhatod létre.</span>'}<button type="button" class="tag-option" data-action="new-tag">＋ Új címke</button></div><input type="hidden" id="selectedTags" value="${esc([...(song?.tags||[])].join('|'))}"></div><div class="switch-row"><div><strong>★ Kedvenc</strong><small>Gyorsan elérhető lesz a kedvenceid között.</small></div><button type="button" id="favoriteSwitch" class="switch ${song?.favorite?'on':''}" aria-label="Kedvenc"></button></div><div class="form-actions"><button type="button" class="btn ghost" data-action="page" data-page="songs">← Vissza a dalokhoz</button><div class="right">${song?'<button type="button" class="btn danger" data-action="delete-song" data-id="'+esc(song.id)+'">Törlés</button>':''}<button class="btn primary large" type="submit">💾 Mentés</button></div></div></form></div>`}
function tagsView(){return `${pageHeader('RENDEZÉS','Kategóriák és címkék','Egy dalhoz több címkét is megadhatsz.')}<div class="panel" style="max-width:680px;margin-top:20px"><div class="field" style="grid-template-columns:1fr auto;align-items:end"><div><label for="newTagInput">Új címke</label><input id="newTagInput" placeholder="Például: Csárdás"></div><button class="btn primary" data-action="create-tag">＋ Létrehozás</button></div><div style="margin-top:18px">${state.tags.map(t=>`<div class="tag-manage"><span class="pill">${esc(t)}</span><span class="small-muted">${state.songs.filter(s=>(s.tags||[]).includes(t)).length} dal</span><button class="btn ghost" data-action="rename-tag" data-tag="${esc(t)}">Átnevezés</button><button class="btn ghost" data-action="delete-tag" data-tag="${esc(t)}">Törlés</button></div>`).join('')||'<p class="small-muted">Még nincsenek címkéid.</p>'}</div></div>`}
function gigList(){return `${pageHeader('SZÍNPADRA KÉSZEN','Fellépés-listák','Állítsd össze előre a műsort, aztán indítsd el az énekes módot.','<button class="btn primary" data-action="new-gig">＋ Új lista</button>')}<div style="max-width:790px;margin-top:20px">${state.gigs.length?state.gigs.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(g=>`<div class="gig-card"><div class="gig-date">${esc(shortDate(g.date))}</div><div class="gig-info"><strong>${esc(g.name)}</strong><small>${esc(dateLabel(g.date))} · ${g.songIds.length} dal</small></div><div class="gig-actions"><button class="btn primary" data-action="start-gig" data-id="${esc(g.id)}">▶ Indítás</button><button class="btn" data-action="edit-gig" data-id="${esc(g.id)}">Szerkesztés</button><button class="btn ghost" data-action="duplicate-gig" data-id="${esc(g.id)}" aria-label="Lista duplikálása">⧉</button></div></div>`).join(''):`<div class="empty"><div class="empty-icon">♫</div><h3>Állítsd össze a műsort</h3><p>Készíts fellépés-listát, rendezd sorba a dalokat, majd indítsd el a képernyő-ébresztő fellépés módot.</p><button class="btn primary" data-action="new-gig">＋ Új fellépés-lista</button></div>`}</div>`}
function gigEditor(){const g=gigById(activeGigId),songs=(g?.songIds||[]).map(id=>songById(id)).filter(Boolean);return `<div style="max-width:850px">${pageHeader(g?'MŰSOR SZERKESZTÉSE':'ÚJ MŰSOR',g?esc(g.name):'Új fellépés-lista','A sorrendet a fogantyúval húzva vagy a nyilakkal módosíthatod.')}<div class="panel form-grid" style="margin-top:20px"><div class="two-col"><div class="field"><label for="gigName">Lista neve *</label><input id="gigName" maxlength="120" value="${esc(g?.name||'')}" placeholder="Például: Lakodalom"></div><div class="field"><label for="gigDate">Dátum</label><input id="gigDate" type="date" value="${esc(g?.date||'')}"></div></div><div class="section-head"><h3>Dalok a listában <span class="small-muted">(${songs.length})</span></h3><button class="btn" data-action="add-gig-songs">＋ Dalok hozzáadása</button></div><div class="gig-songs" id="gigSongs">${songs.map((s,i)=>`<div class="gig-song" draggable="true" data-gig-song="${esc(s.id)}"><span class="drag-handle" title="Húzd a rendezéshez">⠿</span><span class="row-number">${i+1}.</span><span class="song-title">${esc(s.title)}</span><button class="row-more" data-action="move-gig-song" data-id="${esc(s.id)}" data-dir="-1" aria-label="Fel">↑</button><button class="row-more" data-action="move-gig-song" data-id="${esc(s.id)}" data-dir="1" aria-label="Le">↓</button><button class="row-more" data-action="remove-gig-song" data-id="${esc(s.id)}" aria-label="Eltávolítás">×</button></div>`).join('')||'<div class="empty" style="padding:23px"><p style="margin:0">Még nincs dal a listában. Adj hozzá a zenész-könyvedből.</p></div>'}</div><div class="form-actions"><button class="btn ghost" data-action="page" data-page="gigs">← Fellépés-listák</button><div class="right">${g?`<button class="btn" data-action="duplicate-gig" data-id="${esc(g.id)}">⧉ Lista duplikálása</button><button class="btn danger" data-action="delete-gig" data-id="${esc(g.id)}">Törlés</button>`:''}<button class="btn primary large" data-action="save-gig">💾 Lista mentése</button></div></div></div></div>`}
function settingsView(){const s=state.settings;const themes=[['night','🌑 Éjszakai'],['light','☀️ Világos'],['piano','🎹 Zongora'],['stage','🎤 Színpad'],['notes','🎼 Hangjegyek'],['modern','🌌 Modern'],['custom','🖼️ Saját háttér']];return `${pageHeader('SZEMÉLYRE SZABÁS','Beállítások','A megjelenés és az adatmentés mindig ezen a készüléken marad.')}<div class="two-col" style="margin-top:20px;align-items:start"><div class="panel"><div class="section-head"><h3>Megjelenés</h3></div><div class="field"><label>Téma</label><div class="theme-swatches">${themes.map(([id,n])=>`<button class="theme-choice ${s.theme===id?'selected':''}" data-action="theme" data-theme="${id}"><b style="${id==='light'?'background:linear-gradient(90deg,#f8f6f0 50%,#a47d36 50%)':id==='stage'?'background:linear-gradient(90deg,#251725 50%,#db6470 50%)':id==='piano'?'background:linear-gradient(90deg,#08090c 50%,#d6b46a 50%)':''}"></b>${n}</button>`).join('')}</div></div><div class="range-group" style="margin-top:23px"><label class="slider-row"><span>Betűméret</span><input type="range" min="16" max="42" value="${s.font}" data-setting="font"><b id="fontValue">${s.font}px</b></label><label class="slider-row"><span>Sortávolság</span><input type="range" min="1.25" max="2.2" step=".05" value="${s.line}" data-setting="line"><b id="lineValue">${Number(s.line).toFixed(2)}</b></label><label class="slider-row"><span>Sötét réteg átlátszósága</span><input type="range" min=".35" max=".96" step=".01" value="${s.overlay}" data-setting="overlay"><b id="overlayValue">${Math.round(s.overlay*100)}%</b></label></div><div class="field" style="margin-top:20px"><label for="backgroundFile">Saját háttérkép</label><input type="file" accept="image/*" id="backgroundFile"><span class="help">A kép a készüléken marad. Az olvashatóságért sötét réteg takarja.</span>${s.background?'<button class="btn" data-action="remove-background">Háttérkép eltávolítása</button>':''}</div></div><div style="display:grid;gap:15px"><div class="panel"><div class="section-head"><h3>Képernyő</h3></div><div class="switch-row"><div><strong>Ébren tartás Fellépés módban</strong><small>A támogatott böngészőkben nem alszik el a képernyő.</small></div><button class="switch ${s.wake?'on':''}" data-action="toggle-wake" aria-label="Ébren tartás"></button></div><div class="field" style="margin-top:16px"><label for="orientationSelect">Képernyő tájolása</label><select class="select" style="width:100%" id="orientationSelect"><option value="auto" ${s.orientation==='auto'?'selected':''}>Automatikus</option><option value="portrait" ${s.orientation==='portrait'?'selected':''}>Álló</option><option value="landscape" ${s.orientation==='landscape'?'selected':''}>Fekvő</option></select><span class="help">A tájolás zárolását csak az eszköz és a telepített böngésző engedheti.</span></div></div><div class="panel"><div class="section-head"><h3>Adatok és biztonság</h3></div><p class="small-muted">A dalszövegeid nem kerülnek fel szerverre. A mentés JSON-fájlban a dalokat, címkéket, műsorokat és beállításokat tartalmazza.</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:13px"><button class="btn primary" data-action="export">💾 Exportálás</button><button class="btn" data-action="import">📂 Importálás</button><input type="file" id="importFile" accept="application/json,.json" hidden></div><p class="help" style="margin-top:12px">Importáláskor választhatsz a meglévő adatok megtartása, hozzáfűzés és teljes visszaállítás között.</p></div></div></div>`}
function render(){document.body.className=state.settings.theme==='custom'?'':state.settings.theme;const main=$('#main');if(currentSongId){renderReader();return}$('#overlay').innerHTML='';$('.bottom-nav').style.display='flex';$('.topbar').style.display='flex';const views={home:homeView,songs:songsView,favorites:favoritesView,recent:recentView,editor:songEditor,tags:tagsView,gigs:gigList,gigEditor:gigEditor,settings:settingsView};main.innerHTML=(views[page]||homeView)();$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===(page==='gigEditor'?'gigs':page==='editor'?'songs':page==='favorites'||page==='recent'||page==='tags'?'songs':page)));applyReaderStyles();if(modal)renderModal();else $('#overlay').innerHTML=''}
function applyReaderStyles(){document.documentElement.style.setProperty('--song-size',`${state.settings.font}px`);document.documentElement.style.setProperty('--line-height',state.settings.line);document.documentElement.style.setProperty('--scrim',state.settings.overlay);document.documentElement.style.setProperty('--reader-background',state.settings.background?`url("${state.settings.background}")`:'none')}
function renderReader(){const s=songById(currentSongId);if(!s){currentSongId=null;render();return}const performance=!!readerContext?.gigId;document.body.className=state.settings.theme==='custom'?'':state.settings.theme;$('.topbar').style.display=performance?'none':'flex';$('.bottom-nav').style.display=performance?'none':'flex';$('#main').innerHTML=`<section class="song-reader ${performance?'performance-reader':'normal-reader'}"><div class="reader-wrap"><div class="reader-top"><span class="eyebrow">${performance?'🎤 FELLÉPÉS MÓD':'♫ DALSZÖVEG'}</span><button class="reader-close" data-action="close-reader" aria-label="Bezárás">×</button></div><h1 class="reader-title">${esc(s.title)}</h1><div class="reader-meta">${[s.artist,...(s.tags||[])].filter(Boolean).map(esc).join(' · ')}</div><article class="reader-lyrics">${esc(s.lyrics)}</article><div class="reader-controls"><button data-action="previous-song" ${readerNeighbor(-1)?'':'disabled'}>◀ ELŐZŐ</button><button class="favorite" data-action="toggle-favorite" aria-label="Kedvenc">${s.favorite?'★':'☆'}</button><button data-action="next-song" ${readerNeighbor(1)?'':'disabled'}>KÖVETKEZŐ ▶</button></div>${performance?'<button class="btn ghost" style="position:fixed;right:16px;top:50%;writing-mode:vertical-rl;z-index:3" data-action="gig-drawer">☰ Lista</button>':''}</div></section>`;applyReaderStyles()}
function currentSequence(){if(readerContext?.gigId){const g=gigById(readerContext.gigId);return (g?.songIds||[]).filter(id=>songById(id))}if(readerContext?.ids)return readerContext.ids.filter(id=>songById(id));return filteredSongs().map(s=>s.id)}
function readerNeighbor(dir){const a=currentSequence(),i=a.indexOf(currentSongId);return a[i+dir]||null}
async function enterSong(id,ctx=null){const s=songById(id);if(!s)return;s.lastOpened=new Date().toISOString();state.recent=[id,...state.recent.filter(x=>x!==id)].slice(0,20);await persist();currentSongId=id;readerContext=ctx;renderReader();window.scrollTo(0,0)}
function moveSong(dir){const id=readerNeighbor(dir);if(id){currentSongId=id;enterSong(id,readerContext)}}
async function closeReader(){currentSongId=null;readerContext=null;render();await releaseWakeLock()}
let wakeLock=null;async function acquireWakeLock(){if(!state.settings.wake)return;try{if('wakeLock'in navigator)wakeLock=await navigator.wakeLock.request('screen')}catch{notify('A készülék nem engedélyezte a képernyő ébren tartását.')}}async function releaseWakeLock(){try{await wakeLock?.release()}catch{}wakeLock=null}
function renderModal(){if(!modal){$('#overlay').innerHTML='';return}let body='',title=modal.title||'Megerősítés';if(modal.type==='confirm')body=`<p>${esc(modal.message)}</p>`;if(modal.type==='newGig')body=`<div class="form-grid"><div class="field"><label>Lista neve *</label><input id="modalGigName" placeholder="Például: Lakodalom" autofocus></div><div class="field"><label>Dátum</label><input type="date" id="modalGigDate" value="${localDate()}"></div></div>`;if(modal.type==='renameTag')body=`<div class="field"><label>Új címkenév</label><input id="renameTagInput" value="${esc(modal.tag)}" maxlength="40"></div>`;if(modal.type==='newTag')body=`<div class="field"><label>Címke neve</label><input id="modalTagInput" placeholder="Például: Csárdás" maxlength="40"></div>`;if(modal.type==='addSongs')body=`<div class="field"><label>Keress egy dalt, és koppints rá a listához adáshoz</label><input id="addSongSearch" placeholder="Dal keresése…"></div><div id="addSongResults" class="song-list" style="margin-top:12px;max-height:45vh;overflow:auto">${renderAddSongRows('')}</div>`;if(modal.type==='import')body=`<p>A biztonsági mentés <strong>${modal.payload.songs.length} dalt</strong> és <strong>${modal.payload.gigs.length} fellépés-listát</strong> tartalmaz.</p><p>Válaszd ki, hogyan kezeljük a mostani adatokat:</p><div class="form-grid"><button class="btn" data-action="do-import" data-mode="merge">Meglévő adatok megtartása, ütközők kihagyása</button><button class="btn" data-action="do-import" data-mode="append">Importált adatok hozzáadása</button><button class="btn danger" data-action="do-import" data-mode="restore">Teljes visszaállítás a mentésből</button></div>`;let actions=modal.type==='addSongs'?'<button class="btn" data-action="close-modal">Kész</button>':`<button class="btn" data-action="close-modal">Mégsem</button>${modal.type==='confirm'?`<button class="btn ${modal.danger?'danger':'primary'}" data-action="confirm-yes">${esc(modal.confirmText||'Rendben')}</button>`:modal.type==='newGig'?'<button class="btn primary" data-action="confirm-new-gig">Létrehozás</button>':modal.type==='renameTag'?'<button class="btn primary" data-action="confirm-rename-tag">Átnevezés</button>':modal.type==='newTag'?'<button class="btn primary" data-action="confirm-new-tag">Létrehozás</button>':''}`;$('#overlay').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal"><div class="section-head"><h3>${title}</h3><button class="btn ghost" data-action="close-modal">×</button></div>${body}<div class="modal-actions">${actions}</div></section></div>`}
function renderAddSongRows(q){const existing=new Set(gigById(activeGigId)?.songIds||[]);const a=filteredSongs(state.songs,q).filter(s=>!existing.has(s.id));return a.length?a.slice(0,100).map(s=>`<button class="drawer-row" data-action="select-gig-song" data-id="${esc(s.id)}">＋ &nbsp;${esc(s.title)}${s.artist?` <span class="song-artist">${esc(s.artist)}</span>`:''}</button>`).join(''):'<div class="empty" style="padding:20px"><p style="margin:0">Nincs hozzáadható dal.</p></div>'}
function showConfirm(message,yes,{danger=false,confirmText='Törlés'}={}){modal={type:'confirm',message,yes,danger,confirmText};renderModal()}
function cleanText(x){return String(x||'').trim()}
async function saveSong(form){const fd=new FormData(form),title=cleanText(fd.get('title')),lyrics=cleanText(fd.get('lyrics'));if(!title||!lyrics){notify('A cím és a dalszöveg megadása kötelező.');return}const old=editorId?songById(editorId):null,selected=($('#selectedTags')?.value||'').split('|').filter(Boolean);const s={id:old?.id||uid(),title,artist:cleanText(fd.get('artist')),lyrics,tags:selected,favorite:$('#favoriteSwitch')?.classList.contains('on')||false,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),lastOpened:old?.lastOpened||null};if(old)state.songs[state.songs.indexOf(old)]=s;else state.songs.push(s);await persist();editorId=null;notify(old?'Dal elmentve.':'Új dal elmentve.');setPage('songs')}
async function saveGig(){const name=cleanText($('#gigName')?.value);if(!name){notify('Add meg a lista nevét.');$('#gigName')?.focus();return}const old=gigById(activeGigId),g={id:old?.id||uid(),name,date:$('#gigDate')?.value||'',songIds:old?.songIds||[],createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(old)state.gigs[state.gigs.indexOf(old)]=g;else state.gigs.push(g);await persist();activeGigId=null;notify('Fellépés-lista mentve.');setPage('gigs')}
function exportBackup(){const data={format:'stefy-songbook',version:1,exportedAt:new Date().toISOString(),songs:state.songs,tags:state.tags,gigs:state.gigs,recent:state.recent,sort:state.sort,settings:state.settings};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Stefy_Dalszovegek_${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('A biztonsági mentés letöltése elindult.')}
function validateBackup(v){if(!v||typeof v!=='object'||!Array.isArray(v.songs)||!Array.isArray(v.gigs)||!Array.isArray(v.tags))throw Error('bad');const songs=v.songs.map(s=>{if(!s||typeof s.title!=='string'||typeof s.lyrics!=='string')throw Error('bad');return{id:typeof s.id==='string'?s.id:uid(),title:s.title,artist:String(s.artist||''),lyrics:s.lyrics,tags:Array.isArray(s.tags)?s.tags.map(String):[],favorite:!!s.favorite,createdAt:s.createdAt||new Date().toISOString(),updatedAt:s.updatedAt||new Date().toISOString(),lastOpened:s.lastOpened||null}});const songIds=new Set(songs.map(s=>s.id));const gigs=v.gigs.map(g=>{if(!g||typeof g.name!=='string')throw Error('bad');return{id:typeof g.id==='string'?g.id:uid(),name:g.name,date:String(g.date||''),songIds:Array.isArray(g.songIds)?g.songIds.filter(id=>songIds.has(id)):[],createdAt:g.createdAt||new Date().toISOString(),updatedAt:g.updatedAt||new Date().toISOString()}});return{songs,tags:[...new Set(v.tags.filter(x=>typeof x==='string'))],gigs,recent:Array.isArray(v.recent)?v.recent.filter(id=>songIds.has(id)).slice(0,20):[],sort:['title','recent','favorite','newest'].includes(v.sort)?v.sort:'title',settings:{...DEFAULT.settings,...(v.settings&&typeof v.settings==='object'?v.settings:{})}}}
async function applyImport(payload,mode){if(mode==='restore'){state={...payload,settings:{...DEFAULT.settings,...payload.settings}}}else{const identity=s=>`${s.title.trim().toLocaleLowerCase('hu')}|${(s.artist||'').trim().toLocaleLowerCase('hu')}`,known=new Set(state.songs.map(identity)),map=new Map();for(const s of payload.songs){const duplicate=mode==='merge'&&known.has(identity(s));if(duplicate){const found=state.songs.find(x=>identity(x)===identity(s));map.set(s.id,found?.id);continue}const copy={...s,id:state.songs.some(x=>x.id===s.id)?uid():s.id};map.set(s.id,copy.id);state.songs.push(copy);known.add(identity(copy))}for(const t of payload.tags)if(!state.tags.includes(t))state.tags.push(t);for(const g of payload.gigs){const ids=g.songIds.map(id=>map.get(id)).filter(Boolean),copy={...g,id:state.gigs.some(x=>x.id===g.id)?uid():g.id,songIds:ids};if(mode==='merge'&&state.gigs.some(x=>x.name.toLocaleLowerCase('hu')===g.name.toLocaleLowerCase('hu')&&x.date===g.date))continue;state.gigs.push(copy)}}await persist();notify('A biztonsági mentés sikeresen betöltve.');render()}
