document.addEventListener('change',async e=>{if(e.target.id==='sortSelect'){state.sort=e.target.value;await persist();render()}if(e.target.id==='orientationSelect'){state.settings.orientation=e.target.value;await persist();try{if(screen.orientation?.lock&&e.target.value!=='auto')await screen.orientation.lock(e.target.value);else screen.orientation?.unlock?.()}catch{notify('A tájolás zárolását ez a böngésző nem támogatja.')}}if(e.target.id==='backgroundFile'&&e.target.files?.[0]){const file=e.target.files[0];if(file.size>8*1024*1024){notify('A kép legfeljebb 8 MB lehet.');return}const reader=new FileReader();reader.onload=async()=>{state.settings.background=reader.result;state.settings.theme='custom';await persist();render();notify('Háttérkép beállítva.')} ;reader.onerror=()=>notify('A képet nem sikerült beolvasni.');reader.readAsDataURL(file)}if(e.target.id==='importFile'&&e.target.files?.[0]){try{const text=await e.target.files[0].text(),v=JSON.parse(text);importPayload=validateBackup(v);modal={type:'import',title:'Biztonsági mentés visszaállítása',payload:importPayload};renderModal()}catch{notify('A biztonsági mentés nem olvasható. A meglévő adataid változatlanok.')}e.target.value=''}});
